[package]
name = "caliper-docgen-semantic"
description = "TypeScript 7.1 checker backend for caliper-docgen: asks the built-in checker (tsrs) for each component's props"
version = "0.5.0"
edition.workspace = true
license.workspace = true
authors.workspace = true
repository.workspace = true
homepage.workspace = true

[lints]
workspace = true

[dependencies]
caliper-docgen-core       = { path = "../core", version = "0.11.0" }
tokio                     = { workspace = true, features = ["time", "rt", "sync"] }
serde.workspace           = true
serde_json                = { workspace = true, features = ["raw_value"] }
camino.workspace          = true
tracing.workspace         = true
rustc-hash.workspace      = true
tsrs_api.workspace        = true
tsrs_vfs.workspace        = true
tsrs_core.workspace       = true
rmp-serde.workspace       = true
xxhash-rust.workspace     = true
libmimalloc-sys.workspace = true

[target.'cfg(unix)'.dependencies]
libc.workspace            = true

[dev-dependencies]
tempfile.workspace        = true
insta.workspace           = true
# The native binding's allocator, so the gate harness measures memory as the addon's process holds it.
mimalloc                  = { version = "0.1", default-features = false }
            .unwrap();
        }
        (dir, root)
    }

    fn answered(root: &Utf8Path, programs: usize) -> SemanticOutcome {
        let output = extract(&PipelineOptions { src_dirs: vec![root.to_owned()], ..PipelineOptions::default() });
        let request = SemanticRequest::new(root.to_owned(), targets_of(&output));
        let runtime = tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();
        runtime.block_on(run(request, Some(programs)))
    }

    /// A symbol's type is kept by the symbol, not by what it is named or where it is declared: two instantiations of
    /// one generic interface list a property of the same name and declaration, each a symbol of its own with its own
    /// type, and the second component, answered after the first on the same program, is not handed the first's type.
    #[test]
    fn a_kept_symbol_type_is_the_type_of_that_symbol() {
        let (_dir, root) = shared_types_project(0);
        std::fs::write(
            root.join("Boxes.tsx"),
            "interface Box<T> { value: T; label?: string }\n\
             export function Text(props: Box<string>) { return null; }\n\
             export function Count(props: Box<number>) { return null; }\n\
             export function Again(props: Box<string>) { return null; }\n",
        )
        .unwrap();

        let outcome = answered(&root, 1);

        let value = |key: &str| {
            let component = outcome.components.iter().find(|component| component.key == key).unwrap();
            component.props.iter().find(|prop| prop.name == "value").unwrap().prop_type.clone()
        };
        assert_eq!(value("Text"), caliper_docgen_core::types::PropType::String);
        assert_eq!(value("Count"), caliper_docgen_core::types::PropType::Number);
        assert_eq!(value("Again"), caliper_docgen_core::types::PropType::String);
    }

    /// Three programs on the built-in checker, each answering some of the files, give the answer one program gives:
    /// each holds every root file, so what one file declares (here a global augmentation in the last) reaches the
    /// components the other programs answer.
    #[test]
    fn several_programs_answer_as_one_does() {
        let (_dir, root) = shared_types_project(9);

        let one = answered(&root, 1);
        let three = answered(&root, 3);

        assert!(one.diagnostics.is_empty() && one.fallbacks.is_empty(), "{one:?}");
        assert_eq!(one.components.len(), 9);
        for component in &one.components {
            let names: Vec<&str> = component.props.iter().map(|prop| prop.name.as_str()).collect();
            assert!(names.contains(&"fromLastFile") && names.contains(&"fromTypes"), "{names:?}");
        }
        assert_eq!(one, three);
    }

    /// Stands in for the built-in checker's session: it initializes and makes a snapshot of as many programs as asked,
    /// and panics on any question about them, counting how many it was asked.
    struct Panicking {
        asked: Arc<std::sync::atomic::AtomicU32>,
    }

    impl checker::Served for Panicking {
        fn handle(&self, method: &str, params: &[u8]) -> Result<String, checker::Failure> {
            match method {
                "initialize" | "release" => Ok("null".to_string()),
                "createSnapshot" => {
                    let params: serde_json::Value = serde_json::from_slice(params).unwrap();
                    let count = params["createPrograms"].as_array().map_or(1, Vec::len);
                    let projects: Vec<_> = (0..count).map(|n| serde_json::json!({ "id": format!("p{n}") })).collect();
                    Ok(serde_json::json!({ "snapshot": 1, "projects": projects }).to_string())
                }
                _ => {
                    self.asked.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    panic!("checker invariant broken")
                }
            }
        }

        fn discard(&self, _method: &str, _answer: &str) {}

        fn close(&self) {}
    }

    /// A whole-project run on two lanes whose checker panics: the lane that met it fails its file, the other lane
    /// stops, and the run gives every component its structural answer with one diagnostic, never a partial answer.
    #[test]
    fn a_panic_on_one_lane_fails_the_whole_run_to_the_structural_answer() {
        let (_dir, root) = shared_types_project(6);
        let output = extract(&PipelineOptions { src_dirs: vec![root.clone()], ..PipelineOptions::default() });
        let request = SemanticRequest::new(root.clone(), targets_of(&output));
        let asked = Arc::new(std::sync::atomic::AtomicU32::new(0));
        let session = Panicking { asked: Arc::clone(&asked) };
        let checker = Backend::spawn(2, move || session).unwrap();
        let runtime = tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();

        let outcome = runtime.block_on(answer_with(&checker, &request));

        assert!(outcome.components.is_empty(), "{:?}", outcome.components);
        assert_eq!(outcome.diagnostics.len(), 1, "{:?}", outcome.diagnostics);
        let message = &outcome.diagnostics[0].message;
        // Whichever lane's error the run meets first: the panic, the other lane's refusal after it, or a request that
        // was still queued on a lane that stopped.
        let reason = message.strip_prefix("TypeScript checker backend unavailable: the checker stopped answering: ");
        assert!(
            reason.is_some_and(|reason| [
                "panic: checker invariant broken",
                "the built-in checker stopped: a panic unwound through its session",
                "session shut down",
            ]
            .iter()
            .any(|said| reason.contains(said))),
            "{message}"
        );
        // Each lane met the panic at most once: none was asked again after it.
        assert!((1..=2).contains(&asked.load(std::sync::atomic::Ordering::Relaxed)));
        assert!(!checker.is_alive());
        runtime.block_on(checker.shutdown());
    }

    /// Stands in for the checker's session: makes snapshots, refuses every question about them, and counts the
    /// snapshots released.
    struct Refusing {
        released: Arc<std::sync::atomic::AtomicU32>,
    }

    impl checker::Served for Refusing {
        fn handle(&self, method: &str, params: &[u8]) -> Result<String, checker::Failure> {
            match method {
                "initialize" => Ok("null".to_string()),
                "release" => {
                    self.released.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    Ok("null".to_string())
                }
                "createSnapshot" => {
                    let params: serde_json::Value = serde_json::from_slice(params).unwrap();
                    let count = params["createPrograms"].as_array().map_or(1, Vec::len);
                    let projects: Vec<_> = (0..count).map(|n| serde_json::json!({ "id": format!("p{n}") })).collect();
                    Ok(serde_json::json!({ "snapshot": 1, "projects": projects }).to_string())
                }
                _ => Err(checker::Failure { message: "refused".to_string(), panicked: false }),
            }
        }

        fn discard(&self, _method: &str, _answer: &str) {}

        fn close(&self) {}
    }

    /// How many times a run under `teardown` asks the checker to release its snapshot.
    fn releases_under(teardown: Teardown) -> u32 {
        let (_dir, root) = shared_types_project(2);
        let output = extract(&PipelineOptions { src_dirs: vec![root.clone()], ..PipelineOptions::default() });
        let request = SemanticRequest::new(root, targets_of(&output)).with_teardown(teardown);
        let released = Arc::new(std::sync::atomic::AtomicU32::new(0));
        let session = Refusing { released: Arc::clone(&released) };
        let checker = Backend::spawn(1, move || session).unwrap();
        let runtime = tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();
        runtime.block_on(answer_with(&checker, &request));
        runtime.block_on(checker.shutdown());
        released.load(std::sync::atomic::Ordering::Relaxed)
    }

    /// A run that goes on after it (a session, the library) releases its snapshot, even when the checker failed it;
    /// one whose process ends with it does not wait for the release.
    #[test]
    fn only_a_session_run_releases_its_snapshot() {
        assert_eq!(releases_under(Teardown::Session), 1);
        assert_eq!(releases_under(Teardown::OneShot), 0);
        assert_eq!(Teardown::default(), Teardown::Session);
        assert_eq!(SemanticRequest::new(Utf8PathBuf::new(), Vec::new()).teardown, Teardown::Session);
    }

    /// A prop the converter keeps for later components is kept by what makes it, including which of its JSDoc was
    /// asked: a component whose structural pass already described `id` is not handed the description another asked for,
    /// and the one after it is not handed an empty one. The three are in one file, so they are answered in turn and the
    /// later ones find the first one's props kept.
    #[test]
    fn a_kept_prop_is_one_made_by_the_same_question() {
        let (_dir, root) = shared_types_project(0);
        let component = |name: &str| {
            format!(
                "export interface {name}Props extends Base {{ own: number }}\nexport function {name}(props: {name}Props) {{ return null; }}\n"
            )
        };
        let text = format!(
            "import type {{ Base }} from './types';\n{}{}{}",
            component("C0"),
            component("C1"),
            component("C2")
        );
        std::fs::write(root.join("All.tsx"), text).unwrap();
        let output = extract(&PipelineOptions { src_dirs: vec![root.clone()], ..PipelineOptions::default() });
        let mut targets = targets_of(&output);
        for target in &mut targets {
            target.described.clear();
        }
        if let Some(target) = targets.iter_mut().find(|target| target.key == "C1") {
            target.described.insert("id".to_string());
        }
        let runtime = tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();

        let outcome = runtime.block_on(run(SemanticRequest::new(root.clone(), targets), Some(1)));

        let description = |key: &str| {
            let component = outcome.components.iter().find(|component| component.key == key).unwrap();
            component.props.iter().find(|prop| prop.name == "id").unwrap().description.clone()
        };
        assert_eq!(
            (description("C0"), description("C1"), description("C2")),
            ("The id.".into(), String::new(), "The id.".into())
        );
    }

    /// `root`'s components answered on two programs under `budget`.
    fn answered_under(root: &Utf8Path, budget: Option<HeapBudget>) -> SemanticOutcome {
        let output = extract(&PipelineOptions { src_dirs: vec![root.to_owned()], ..PipelineOptions::default() });
        let mut request = SemanticRequest::new(root.to_owned(), targets_of(&output));
        request.heap_budget = budget;
        let runtime = tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();
        runtime.block_on(run(request, Some(2)))
    }

    /// The reads of [`a_run_past_its_heap_budget_leaves_the_rest_structural_with_one_warning`]'s meter.
    static READS: AtomicU64 = AtomicU64::new(0);

    /// A heap that grows by a byte at each read.
    fn growing() -> u64 {
        READS.fetch_add(1, Ordering::Relaxed)
    }

    /// A run whose heap passes its budget part way finishes: the components answered before keep the checker's answer,
    /// exactly as an unbounded run gives it, every other one is left to its structural result, and one warning names
    /// them all. Nothing reads the heap or asks the checker once it is past: the reads stop at the one that passed,
    /// plus at most one per lane that was reading at the same moment.
    #[test]
    fn a_run_past_its_heap_budget_leaves_the_rest_structural_with_one_warning() {
        let (_dir, root) = shared_types_project(24);
        // The reads a whole run makes, so the budget can be passed three quarters of the way through: eight lanes
        // answer the 24 files in three rounds, so the first round is done by then whatever order the lanes run in.
        let unbounded = answered_under(&root, Some(HeapBudget::metered(u64::MAX, growing)));
        assert_eq!(unbounded.components.len(), 24, "{unbounded:?}");
        let budget = READS.swap(0, Ordering::Relaxed) * 3 / 4;

        let outcome = answered_under(&root, Some(HeapBudget::metered(budget, growing)));

        let answered = outcome.components.len();
        assert!((1..24).contains(&answered), "{answered} of 24 answered");
        for component in &outcome.components {
            assert!(unbounded.components.contains(component), "{} differs", component.key);
        }
        assert!(outcome.fallbacks.is_empty(), "{:?}", outcome.fallbacks);
        let [warning] = outcome.diagnostics.as_slice() else { panic!("{:?}", outcome.diagnostics) };
        assert_eq!(warning.severity, caliper_docgen_core::types::DiagnosticSeverity::Warning);
        assert!(warning.message.starts_with(&format!("{} component(s) kept their structural result", 24 - answered)));
        assert!(warning.message.contains("depends on timing"), "{}", warning.message);
        let mut all: Vec<&str> = outcome.components.iter().map(|component| component.key.as_str()).collect();
        all.extend(warning.affects.iter().map(String::as_str));
        all.sort_unstable();
        let mut expected: Vec<&str> = unbounded.components.iter().map(|component| component.key.as_str()).collect();
        expected.sort_unstable();
        assert_eq!(all, expected);
        let reads = READS.load(Ordering::Relaxed);
        assert!(reads <= budget + 1 + FILES_IN_FLIGHT as u64, "{reads} reads");
    }

    /// A budget the heap never reaches changes nothing: the answer is the unbounded one. The machine's budget is read
    /// against mimalloc's commit, which in this test binary (system allocator) is only mimalloc's own; the Chakra run
    /// in the PR shows the meter against a real heap.
    #[test]
    fn a_budget_never_reached_changes_nothing() {
        let (_dir, root) = shared_types_project(12);

        let bounded = answered_under(&root, Some(HeapBudget::machine()));
        let unbounded = answered_under(&root, None);

        assert!(bounded.diagnostics.is_empty() && bounded.fallbacks.is_empty(), "{bounded:?}");
        assert_eq!(bounded.components.len(), 12);
        assert_eq!(bounded, unbounded);
    }
}

