    #[test]
    fn a_run_that_was_refused_a_file_keeps_no_answer() {
        let (_dir, root, cache) = project();
        let depth = crate::checker::MAX_NESTING + 1;
        std::fs::write(
            root.join("tone.ts"),
            format!("export type Tone = {}string{};\n", "{ a: ".repeat(depth), " }".repeat(depth)),
        )
