import fs from "node:fs";
const dir = "/tmp/claude-501/ev";
const med = (a) => { const s = [...a].sort((x, y) => x - y); return s[Math.floor(s.length / 2)]; };
const strip = (o) => { const { stats, ...rest } = o; return rest; };
const canon = (v) => JSON.stringify(v, (k, x) => (x && typeof x === "object" && !Array.isArray(x) ? Object.fromEntries(Object.keys(x).sort().map((k) => [k, x[k]])) : x));
for (const name of ["chakra", "mantine", "shadcn"]) {
  const res = { base: { cpu: [], rss: [] }, new: { cpu: [], rss: [] } };
  let identical = true, degraded = [];
  let ref = null;
  for (let i = 1; i <= 5; i++) {
    for (const v of ["base", "new"]) {
      const j = JSON.parse(fs.readFileSync(`${dir}/${name}.${v}.${i}.json`, "utf8"));
      const text = fs.readFileSync(`${dir}/${name}.${v}.${i}.time`, "utf8");
      const m = text.match(/([\d.]+) real\s+([\d.]+) user\s+([\d.]+) sys/);
      const rss = Number(text.match(/(\d+)\s+maximum resident/)[1]);
      const diags = JSON.stringify(j.diagnostics ?? []);
      const bad = /checker|SEMANTIC_BACKEND/i.test(diags) && /unavailable|stopped|kept their structural/i.test(diags);
      if (bad) degraded.push(`${v}${i}`);
      const c = canon(strip(j));
      ref ??= c;
      if (c !== ref) { identical = false; console.log("DIFF", name, v, i); }
      if (!bad) { res[v].cpu.push(Number(m[2]) + Number(m[3])); res[v].rss.push(rss / 1048576); }
